<script>
  import { flattenArrayFields, formDataToObject } from '@splendidlabz/utils'
  import { randomString, sanitize as sanitizeFn } from '@splendidlabz/utils/dom'
  import Status from '../Status.svelte'
  import Honeypot from './Honeypot.svelte'

  let {
    ref = $bindable(null),
    id = $bindable(randomString()),
    class: klass = '',
    method = 'post',
    action = null,
    sanitize = true,
    preventSpam = true,
    honeypotName = 'hp',
    honeypotDuration = 2000,
    onsubmit = null,
    children,
    status,
    statusText,
    ...rest
  } = $props()

  let honeypotValue = $state('')
  let formStartTime = $state(Date.now())
  let hasInteraction = $state(false)

  function checkForInteraction() {
    hasInteraction = true
  }

  function submit(event) {
    const form = event.target
    event.preventDefault()

    // Format form data before submitting
    let data = formDataToObject(new FormData(form))
    if (sanitize) data = sanitizeFn(data)
    data = flattenArrayFields(data)

    // Enhanced spam prevention
    if (preventSpam) {
      const fillTime = Date.now() - formStartTime
      const isTooFast = fillTime < honeypotDuration
      const hasHoneypotValue = data[honeypotName]?.trim()
      const noInteraction = !hasInteraction
      if (isTooFast || hasHoneypotValue || noInteraction) return
    }

    if (!onsubmit) return form.submit()
    else onsubmit(data)
  }
</script>

<form
  bind:this={ref}
  {id}
  {...rest}
  class="form {klass}"
  {action}
  {method}
  onkeydown={checkForInteraction}
  onmousemove={checkForInteraction}
  onsubmit={submit}
  ontouchstart={checkForInteraction}
>
  {#if preventSpam}
    <Honeypot name={honeypotName} bind:value={honeypotValue} />
  {/if}
  {@render children?.()}
</form>
<Status for={id} {status} {statusText} />
